/**
 * The measured tables (palette/restHeights.ts, restGrids.ts, hangGrids.ts, coverHoles.ts), generated by
 * `npm run render -- rests` from the game's meshes: each lists every piece the bundled palettes name for it and no other,
 * each entry was read on the collider the palette builds the piece with (else it is stale and not applied:
 * palette/measured.ts), every grid parses, and no table was edited by hand (its header's content hash). Reads the
 * repository's files only: never the install.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  checkTableHash,
  coverPieces,
  floorHoleOf,
  hangGridOf,
  hangPieces,
  leavesFloorHole,
  loadPalettes,
  measuredRest,
  parseRestGrid,
  restGridOf,
  restHeight,
  restPieces,
  restTop,
  staleMeasured,
  type Measured,
  type RestPiece,
} from "../../../src/palette";
import { MEASURED_HOLES, UNREAD_HOLES } from "../../../src/palette/coverHoles";
import { HANG_GRIDS, UNREAD_HANG_GRIDS } from "../../../src/palette/hangGrids";
import { MEASURED_REST_GRIDS, UNREAD_REST_GRIDS } from "../../../src/palette/restGrids";
import { MEASURED_RESTS, UNREAD_RESTS } from "../../../src/palette/restHeights";

const RERUN =
  "run `npm run render -- rests` on a machine with TaleSpire installed (it rewrites the measured tables)";

const palettes = loadPalettes().palettes;

const TABLES: ReadonlyArray<{
  file: string;
  table: Readonly<Record<string, Measured>>;
  unread: readonly string[];
  pieces: readonly RestPiece[];
}> = [
  { file: "restHeights.ts", table: MEASURED_RESTS, unread: UNREAD_RESTS, pieces: restPieces(palettes) },
  {
    file: "restGrids.ts",
    table: MEASURED_REST_GRIDS,
    unread: UNREAD_REST_GRIDS,
    pieces: restPieces(palettes),
  },
  { file: "hangGrids.ts", table: HANG_GRIDS, unread: UNREAD_HANG_GRIDS, pieces: hangPieces(palettes) },
  { file: "coverHoles.ts", table: MEASURED_HOLES, unread: UNREAD_HOLES, pieces: coverPieces(palettes) },
];

describe.each(TABLES.map((t) => [t.file, t] as const))("the measured table palette/%s", (file, t) => {
  const ids = new Set(t.pieces.map((p) => p.asset));

  it("lists every piece of its roles in the bundled palettes, measured or unread, and was read on its collider", () => {
    const missing = t.pieces
      .filter((p) => !Object.hasOwn(t.table, p.asset) && !t.unread.includes(p.asset))
      .map((p) => `${p.name} (${p.asset})`);
    expect(missing, `pieces never measured: ${RERUN}`).toEqual([]);
    // a piece the palette now builds with another collider (a game update reshaped it): its reading is not applied
    expect(staleMeasured(t.table, t.pieces), `stale: ${RERUN}`).toEqual([]);
  });

  it("names no piece the bundled palettes do not (numbers for the palettes' own pieces only)", () => {
    const extra = [...Object.keys(t.table), ...t.unread].filter((id) => !ids.has(id));
    expect(extra, `ids no bundled palette names: ${RERUN}`).toEqual([]);
  });

  it("is as the measuring wrote it: its header's content hash is its body's", () => {
    const text = readFileSync(
      fileURLToPath(new URL(`../../../src/palette/${file}`, import.meta.url)),
      "utf8",
    );
    const h = checkTableHash(text);
    expect(h.stated, `palette/${file} states no content hash: ${RERUN}`).not.toBeNull();
    expect(h.actual, `palette/${file} was edited by hand: do not; ${RERUN}`).toBe(h.stated);
  });
});

describe("measured readings", () => {
  it("every grid parses", () => {
    for (const [id, m] of [...Object.entries(MEASURED_REST_GRIDS), ...Object.entries(HANG_GRIDS)])
      expect(parseRestGrid(m.grid), id).not.toBeNull();
  });

  it("a hand edit of a table's body is told from the measuring's own text", () => {
    const text = readFileSync(
      fileURLToPath(new URL("../../../src/palette/coverHoles.ts", import.meta.url)),
      "utf8",
    );
    const edited = text.replace(/hole: 0\.\d+/, "hole: 0");
    expect(edited).not.toBe(text);
    expect(checkTableHash(edited).ok).toBe(false);
  });

  it("a piece the palette builds with another collider than it was measured on is treated as never measured", () => {
    const bench = restPieces(palettes).find((p) => p.name === "Workbench");
    if (!bench) throw new Error("fixture: the bundled palettes have a Workbench");
    const reshaped = { ...bench.geom, size: { ...bench.geom.size, y: bench.geom.size.y + 0.2 } };
    const box = { min: { y: 1 }, max: { y: 1 + reshaped.size.y } };
    // as measured: its work top, under its raised back
    expect(measuredRest(bench.asset, bench.geom)).toBeLessThan(bench.geom.size.y - 0.3);
    expect(restGridOf(bench.asset, bench.geom)).toBeDefined();
    // reshaped: its box top, and no grid
    expect(measuredRest(bench.asset, reshaped)).toBeUndefined();
    expect(restHeight(bench.asset, reshaped, true)).toBe(reshaped.size.y);
    expect(restTop(bench.asset, reshaped, box, true)).toBe(box.max.y);
    expect(restGridOf(bench.asset, reshaped)).toBeUndefined();
    expect(staleMeasured(MEASURED_RESTS, [{ ...bench, geom: reshaped }])).toHaveLength(1);

    const holed = coverPieces(palettes).find((p) => leavesFloorHole(p.asset, p.geom));
    if (!holed) throw new Error("fixture: a bundled floor piece leaves a hole");
    const wider = { ...holed.geom, size: { ...holed.geom.size, x: holed.geom.size.x + 1 } };
    expect(floorHoleOf(holed.asset, wider)).toBeUndefined();
    expect(leavesFloorHole(holed.asset, wider)).toBe(false);

    const canopy = hangPieces(palettes)[0];
    if (!canopy) throw new Error("fixture: the bundled palettes have a stall canopy");
    expect(hangGridOf(canopy.asset, canopy.geom)).toBeDefined();
    expect(
      hangGridOf(canopy.asset, { size: { ...canopy.geom.size, z: canopy.geom.size.z + 0.5 } }),
    ).toBeUndefined();
  });
});
